{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || join(here, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'content-type': type, 'cache-control': 'no-store' });
  res.end(typeof body === 'string' ? body : JSON.stringify(body));
};

async function bodyJson(req) {
  let raw = '';
  for await (const chunk of req) raw += chunk;
  try { return JSON.parse(raw); } catch { return null; }
}

const page = await readFile(join(here, 'index.html'), 'utf8');
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') return send(res, 200, { status: 'ok' });
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    return send(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY id').all());
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    const body = await bodyJson(req);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return send(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return send(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    const project = db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) return send(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') {
      return send(res, 200, db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId));
    }
    if (req.method === 'POST') {
      const body = await bodyJson(req);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) return send(res, 400, { error: 'Task title is required' });
      const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return send(res, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: 0 });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (req.method === 'PATCH' && taskMatch) {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const body = await bodyJson(req);
    if (typeof body?.completed !== 'boolean') return send(res, 400, { error: 'Completion state is required' });
    const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
    if (!result.changes) return send(res, 404, { error: 'Task not found' });
    return send(res, 200, { id: taskId, projectId, completed: body.completed ? 1 : 0 });
  }
  const match = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && match) {
    const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(match[1]));
    return project ? send(res, 200, project) : send(res, 404, { error: 'Project not found' });
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    return send(res, 200, page, 'text/html; charset=utf-8');
  }
  return send(res, 404, { error: 'Not found' });
});

server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #202632; background: #f4f6f9; }
    * { box-sizing: border-box; }
    body { margin: 0; padding: 48px 20px; }
    main { max-width: 760px; margin: 0 auto; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .task-row { background: white; border: 1px solid #dce1e8; border-radius: 10px; padding: 20px; }
    form { display: flex; align-items: end; gap: 12px; flex-wrap: wrap; }
    label { display: grid; gap: 7px; font-weight: 600; flex: 1 1 280px; }
    input { min-height: 42px; border: 1px solid #aab3c0; border-radius: 6px; padding: 8px 10px; font: inherit; }
    button { min-height: 42px; padding: 8px 16px; border: 0; border-radius: 6px; background: #315bd6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #2449b9; }
    button:focus-visible, input:focus-visible { outline: 3px solid #96b4ff; outline-offset: 2px; }
    #message { min-height: 24px; margin: 12px 0; color: #a12727; }
    #projects { display: grid; gap: 10px; margin-top: 20px; }
    #tasks { display: grid; gap: 10px; margin-top: 16px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .task-row { display: flex; align-items: center; gap: 12px; }
    .task-row label { display: flex; align-items: center; gap: 10px; flex: 1; }
    .task-row input { min-height: 20px; width: 20px; }
    #task-form { margin-top: 24px; }
    #task-message { min-height: 24px; color: #a12727; }
    .project-name { overflow-wrap: anywhere; }
    .back { margin-bottom: 20px; background: #465365; }
    [hidden] { display: none !important; }
  </style>
</head>
<body>
  <main>
    <section id="list-view">
      <h1>Workboard</h1>
      <form id="create-form">
        <label for="project-name">Project name</label>
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </form>
      <p id="message" role="alert" aria-live="polite"></p>
      <div id="projects" aria-label="Projects"></div>
    </section>
    <section id="project-view" hidden>
      <button class="back" id="back-button" type="button">Projects</button>
      <h1 id="project-title"></h1>
      <form id="task-form">
        <label for="task-title">Task title</label>
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit">Create task</button>
      </form>
      <p id="task-message" role="alert" aria-live="polite"></p>
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option>All</option><option>Open</option><option>Completed</option>
      </select>
      <div id="tasks" aria-label="Tasks"></div>
    </section>
  </main>
  <script>
    const listView = document.querySelector('#list-view');
    const projectView = document.querySelector('#project-view');
    const projectList = document.querySelector('#projects');
    const message = document.querySelector('#message');
    const tasks = document.querySelector('#tasks');
    const taskFilter = document.querySelector('#task-filter');
    let activeProjectId = null;
    let projectTasks = [];

    function showList() {
      activeProjectId = null;
      listView.hidden = false;
      projectView.hidden = true;
      document.title = 'Workboard';
      loadProjects();
    }

    async function openProject(id) {
      const response = await fetch(`/api/projects/${id}`);
      if (!response.ok) { history.replaceState({}, '', '/'); showList(); return; }
      const project = await response.json();
      activeProjectId = String(id);
      document.querySelector('#project-title').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      listView.hidden = true;
      projectView.hidden = false;
      await loadTasks();
    }

    async function loadTasks() {
      if (!activeProjectId) return;
      const response = await fetch(`/api/projects/${activeProjectId}/tasks`);
      if (!response.ok) return;
      projectTasks = await response.json();
      renderTasks();
    }

    function renderTasks() {
      tasks.replaceChildren();
      const filter = taskFilter.value;
      for (const task of projectTasks) {
        if (filter === 'Open' && task.completed || filter === 'Completed' && !task.completed) continue;
        const row = document.createElement('div');
        row.dataset.testid = 'task-row';
        row.className = 'task-row';
        const label = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = Boolean(task.completed);
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked })
          });
          if (response.ok) {
            task.completed = checkbox.checked ? 1 : 0;
            renderTasks();
          }
        });
        const title = document.createElement('span');
        title.textContent = task.title;
        label.append(checkbox, title);
        row.append(label);
        tasks.append(row);
      }
    }

    async function loadProjects() {
      const response = await fetch('/api/projects');
      const projects = await response.json();
      projectList.replaceChildren();
      for (const project of projects) {
        const row = document.createElement('div');
        row.dataset.testid = 'project-row';
        row.className = 'project-row';
        const name = document.createElement('span');
        name.className = 'project-name';
        name.textContent = project.name;
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = 'Open project';
        button.addEventListener('click', () => {
          history.pushState({}, '', `/projects/${project.id}`);
          openProject(project.id);
        });
        row.append(name, button);
        projectList.append(row);
      }
    }

    document.querySelector('#create-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#project-name');
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ name: input.value })
      });
      if (!response.ok) {
        const result = await response.json();
        message.textContent = result.error || 'Project name is required';
        return;
      }
      message.textContent = '';
      input.value = '';
      await loadProjects();
    });

    document.querySelector('#back-button').addEventListener('click', () => {
      activeProjectId = null;
      history.pushState({}, '', '/');
      showList();
    });
    document.querySelector('#task-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#task-title');
      const response = await fetch(`/api/projects/${activeProjectId}/tasks`, {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ title: input.value })
      });
      if (!response.ok) {
        const result = await response.json();
        document.querySelector('#task-message').textContent = result.error || 'Task title is required';
        return;
      }
      document.querySelector('#task-message').textContent = '';
      input.value = '';
      await loadTasks();
    });
    taskFilter.addEventListener('change', renderTasks);
    addEventListener('popstate', () => {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      match ? openProject(match[1]) : showList();
    });
    const initial = location.pathname.match(/^\/projects\/(\d+)$/);
    initial ? openProject(initial[1]) : showList();
  </script>
</body>
</html>
